#!/usr/bin/env node
/**
 * Promote a Contentful environment alias to a new target.
 *
 * Flips both the 'production' alias and the built-in 'master' alias
 * atomically — they always stay in sync so neither points to a stale environment.
 *
 * Usage:
 *   npm run promote:alias -- --target release-2025-08
 *   npm run promote:alias -- --target release-2025-08 --dry-run
 *
 * Release workflow:
 *   1. Create a release environment (clone master in Contentful web UI or via CMA)
 *   2. Install the content model:  npm run install:contentful -- --target release-2025-08
 *   3. Test via direct environment ID (bypasses alias)
 *   4. Promote:         npm run promote:alias -- --target release-2025-08
 *   5. Retain old environment for 14 days, then delete
 */

import { checkEnv, createClient, log } from './_shared.mjs';

checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);

const args = process.argv.slice(2);
const targetIdx = args.indexOf('--target');
const TARGET = targetIdx !== -1 ? args[targetIdx + 1] : null;
const DRY_RUN = args.includes('--dry-run');

if (!TARGET) {
  log.error('--target <environmentId> is required.');
  console.error('  Example: npm run promote:alias -- --target release-2025-08\n');
  process.exit(1);
}

const ALIASES_TO_FLIP = ['production', 'master'];

async function main() {
  const client = createClient();

  // Verify the target environment exists and is ready
  let targetEnv;
  try {
    targetEnv = await client.environment.get({ environmentId: TARGET });
  } catch {
    log.error(`Environment '${TARGET}' not found in space '${process.env.CONTENTFUL_SPACE_ID}'.`);
    process.exit(1);
  }

  const status = targetEnv.sys.status?.sys?.id;
  if (status !== 'ready') {
    log.error(`Environment '${TARGET}' is not ready (status: ${status ?? 'unknown'}).`);
    process.exit(1);
  }

  // Read current alias state
  const { items: aliases } = await client.environmentAlias.getMany({});
  const currentTargets = Object.fromEntries(aliases.map((a) => [a.sys.id, a.environment.sys.id]));

  log.section('Alias promotion');
  console.log(`  Target environment: ${TARGET}`);

  for (const aliasId of ALIASES_TO_FLIP) {
    const current = currentTargets[aliasId] ?? '(none)';
    if (current === TARGET) {
      log.skip(`Alias '${aliasId}' already points to '${TARGET}'`);
      continue;
    }
    console.log(`  ${aliasId}: ${current} → ${TARGET}`);
    if (!DRY_RUN) {
      await client.environmentAlias.createOrUpdate(
        { environmentAliasId: aliasId },
        { environment: { sys: { type: 'Link', linkType: 'Environment', id: TARGET } } },
      );
      log.success(`Alias '${aliasId}' → '${TARGET}'`);
    } else {
      log.info(`[dry-run] Would flip alias '${aliasId}' → '${TARGET}'`);
    }
  }

  if (!DRY_RUN) {
    console.log(`\n  ✅  Production now points to '${TARGET}'.`);
    console.log(`  ℹ️   Retain previous environment for 14 days before deleting.\n`);
  }
}

main().catch((err) => {
  log.error(err.message ?? err);
  process.exit(1);
});

