#!/usr/bin/env node
/**
 * Bootstrap the Zimmermann Contentful space.
 *
 * Creates environments, locales, per-environment API keys, and the production
 * alias for the six-tier delivery pipeline. Idempotent — safe to re-run.
 *
 * Tier topology:
 *   DEV (dev) → TEST (test) → OMS INT (sit) → STAGE (staging) → UAT (uat) → PROD (master / production alias)
 *
 * Usage:
 *   npm run setup:contentful
 *   npm run setup:contentful -- --dry-run
 *
 * Required env vars (via .env):
 *   CONTENTFUL_MANAGEMENT_TOKEN, CONTENTFUL_SPACE_ID
 */

import {
  checkEnv,
  createClient,
  pollForReady,
  getExistingEnvironmentIds,
  getExistingLocaleCodes,
  log,
} from './_shared.mjs';

const DRY_RUN = process.argv.includes('--dry-run');

